// Des: Tests contact backups: sealed files, weekly, verify, scrub, restore
// Flo: temp dir + mock store > backups > assert files and objects
// I/O: contacts > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const cstr = @import("st-carz-stor.zig"); const stor = @import("st-cont-stor.zig"); const back = @import("sy-cont-back.zig"); const cryp = @import("ut-cryp-aead.zig"); const typz = @import("pa-carz-type.zig"); const cmok = @import("sy-clou-mock.zig");
const NOWZ: i64 = 1_795_600_000_000; const WEKZ: i64 = 7 * 86_400_000;
fn mkzz(urlz: []const u8, cnam: []const u8, phon: []const u8, sell: []const u8) typz.Carz { return .{ .urlz = urlz, .site = "x.vn", .make = "Toyota", .year = 2020, .prov = "Hà Nội", .cnam = cnam, .phon = phon, .sell = sell, .cadd = "1 Phố Huế", .cdes = "Bán xe" }; }
const Rigg = struct { tmpz: std.testing.TmpDir, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, keyz: [32]u8, fn upzz(self: *Rigg) !void { const allo = std.testing.allocator; self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); std.testing.io.random(&self.keyz); var stoz = try cstr.storOpen(&self.dbzz, NOWZ); try stor.contSave(&stoz, mkzz("https://x.vn/a-1", "Lê Văn A", "0966353678", "private"), NOWZ, true); try stor.contSave(&stoz, mkzz("https://x.vn/a-2", "Salon Hai Auto", "0933222111", "dealer"), NOWZ, true); } fn down(self: *Rigg) void { self.aren.deinit(); self.dbzz.close(); std.testing.allocator.free(self.dirz); self.tmpz.cleanup(); } };
fn fileRead(rig3: *Rigg, name: []const u8) ![]u8 { const path = try std.fs.path.join(rig3.aren.allocator(), &.{ rig3.dirz, "bkup", name }); return std.Io.Dir.cwd().readFileAlloc(std.testing.io, path, rig3.aren.allocator(), .limited(1 << 20)); }
test "local: sealed latest and a write-once weekly file, rotation keeps the newest weeks, verify opens everything" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const allo = rig3.aren.allocator(); const rsl1 = try back.backLoca(allo, std.testing.io, &rig3.dbzz, rig3.dirz, rig3.keyz, NOWZ, 2); try std.testing.expectEqual(@as(u32, 2), rsl1.rows); const latz = try fileRead(&rig3, "cont-latest.enc"); try std.testing.expect(std.mem.indexOf(u8, latz, "0966353678") == null); try std.testing.expect(std.mem.indexOf(u8, latz, "Lê Văn") == null);
    var wknz: [64]u8 = undefined; const wekn = try std.fmt.bufPrint(&wknz, "cont-{d}.enc", .{@import("ru-carz-roll.zig").weekOfzz(NOWZ)}); const wka1 = try fileRead(&rig3, wekn); _ = try back.backLoca(allo, std.testing.io, &rig3.dbzz, rig3.dirz, rig3.keyz, NOWZ + 1000, 2); const wkb1 = try fileRead(&rig3, wekn); try std.testing.expectEqualSlices(u8, wka1, wkb1); _ = try back.backLoca(allo, std.testing.io, &rig3.dbzz, rig3.dirz, rig3.keyz, NOWZ + WEKZ, 2); const rsl4 = try back.backLoca(allo, std.testing.io, &rig3.dbzz, rig3.dirz, rig3.keyz, NOWZ + 2 * WEKZ, 2); try std.testing.expectEqual(@as(u32, 2), rsl4.week); try std.testing.expectError(error.FileNotFound, fileRead(&rig3, wekn));
    const verz = try back.backVeri(allo, std.testing.io, rig3.dirz, rig3.keyz); try std.testing.expectEqual(@as(u32, 3), verz.fils); try std.testing.expectEqual(@as(u32, 0), verz.bads); try std.testing.expectEqual(@as(u32, 2), verz.late); var badz = rig3.keyz; badz[3] ^= 1; try std.testing.expectEqual(@as(u32, 3), (try back.backVeri(allo, std.testing.io, rig3.dirz, badz)).bads); }
test "cloud: latest and weekly copies are sealed, an unchanged week sends nothing, a new week sends two and prunes, a dead store fails and retries" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const allo = rig3.aren.allocator(); var cldz = cmok.Mock.init(std.testing.allocator); defer cldz.deinit(); const sto1 = cldz.store(); const rsl1 = try back.backClou(allo, std.testing.io, &rig3.dbzz, sto1, rig3.keyz, NOWZ, 2); try std.testing.expectEqual(@as(u8, 2), rsl1.sent); try std.testing.expectEqual(@as(usize, 2), cldz.map.count()); var itzz = cldz.map.iterator(); while (itzz.next()) |entz| { try std.testing.expect(std.mem.indexOf(u8, entz.value_ptr.*, "0966353678") == null); try std.testing.expect(std.mem.startsWith(u8, entz.key_ptr.*, "cont/")); }
    const rsl2 = try back.backClou(allo, std.testing.io, &rig3.dbzz, sto1, rig3.keyz, NOWZ + 1000, 2); try std.testing.expect(rsl2.same); var stoz = try cstr.storOpen(&rig3.dbzz, NOWZ); try stor.contSave(&stoz, mkzz("https://x.vn/a-3", "Mai", "0911000222", "private"), NOWZ + 2000, true); const rsl3 = try back.backClou(allo, std.testing.io, &rig3.dbzz, sto1, rig3.keyz, NOWZ + 3000, 2); try std.testing.expectEqual(@as(u8, 1), rsl3.sent); _ = try back.backClou(allo, std.testing.io, &rig3.dbzz, sto1, rig3.keyz, NOWZ + WEKZ, 2); try stor.contSave(&stoz, mkzz("https://x.vn/a-4", "Nam", "0911000333", "private"), NOWZ + WEKZ, true); _ = try back.backClou(allo, std.testing.io, &rig3.dbzz, sto1, rig3.keyz, NOWZ + WEKZ + 5, 2); try stor.contSave(&stoz, mkzz("https://x.vn/a-5", "Oanh", "0911000444", "private"), NOWZ + 2 * WEKZ, true); const rsl6 = try back.backClou(allo, std.testing.io, &rig3.dbzz, sto1, rig3.keyz, NOWZ + 2 * WEKZ + 5, 2); try std.testing.expectEqual(@as(u8, 2), rsl6.sent); try std.testing.expectEqual(@as(usize, 3), cldz.map.count());
    cldz.stoo = true; try stor.contSave(&stoz, mkzz("https://x.vn/a-6", "Phuc", "0911000555", "private"), NOWZ + 3 * WEKZ, true); try std.testing.expect(std.meta.isError(back.backClou(allo, std.testing.io, &rig3.dbzz, sto1, rig3.keyz, NOWZ + 3 * WEKZ, 2))); cldz.stoo = false; const rsl8 = try back.backClou(allo, std.testing.io, &rig3.dbzz, sto1, rig3.keyz, NOWZ + 3 * WEKZ, 2); try std.testing.expectEqual(@as(u8, 2), rsl8.sent); }
test "scrub after forget rewrites every local and cloud copy without that contact; restore brings the rest back" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const allo = rig3.aren.allocator(); var cldz = cmok.Mock.init(std.testing.allocator); defer cldz.deinit(); const sto1 = cldz.store(); _ = try back.backLoca(allo, std.testing.io, &rig3.dbzz, rig3.dirz, rig3.keyz, NOWZ, 4); _ = try back.backClou(allo, std.testing.io, &rig3.dbzz, sto1, rig3.keyz, NOWZ, 4); var stoz = try cstr.storOpen(&rig3.dbzz, NOWZ); const cids = try stor.contLook(&stoz, allo, "0966 353 678"); try std.testing.expectEqual(@as(usize, 1), cids.len); try std.testing.expectEqual(@as(u32, 1), try stor.contForg(&stoz, allo, "0966 353 678")); const hitz = try back.backScru(allo, std.testing.io, rig3.dirz, sto1, rig3.keyz, cids); try std.testing.expectEqual(@as(u32, 4), hitz);
    const verz = try back.backVeri(allo, std.testing.io, rig3.dirz, rig3.keyz); try std.testing.expectEqual(@as(u32, 1), verz.late); try std.testing.expectEqual(@as(u32, 0), verz.bads); var itzz = cldz.map.iterator(); while (itzz.next()) |entz| { const open = try cryp.sealOpen(allo, rig3.keyz, entz.value_ptr.*, "cont"); try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, open, "\n")); try std.testing.expect(std.mem.indexOf(u8, open, cids[0]) == null); }
    var tmp2 = std.testing.tmpDir(.{}); defer tmp2.cleanup(); const dir2 = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmp2.sub_path}); var dbz2 = try inde.pageOpen(std.testing.allocator, std.testing.io, dir2); defer dbz2.close(); const path = try std.fs.path.join(allo, &.{ rig3.dirz, "bkup", "cont-latest.enc" }); try std.testing.expectEqual(@as(u32, 1), try back.backRest(allo, std.testing.io, &dbz2, rig3.keyz, path)); var badz = rig3.keyz; badz[0] ^= 1; try std.testing.expectError(error.BadSeal, back.backRest(allo, std.testing.io, &dbz2, badz, path)); }
